    public required string Description { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset Timestamp { get; init; }
}

using sv_1cfa675c18634d4d958ac8664a424033.Client.Models;

namespace sv_1cfa675c18634d4d958ac8664a424033.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_1cfa675c18634d4d958ac8664a424033.Client.Models;
using sv_1cfa675c18634d4d958ac8664a424033.Client.Services;

namespace sv_1cfa675c18634d4d958ac8664a424033.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 6, 8, 9, 0, 0, TimeSpan.FromHours(-5)) },
                new StatusUpdate { Description = "Departed facility", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 6, 8, 14, 30, 0, TimeSpan.FromHours(-5)) },
                new StatusUpdate { Description = "Arrived at sort facility", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 6, 9, 22, 15, 0, TimeSpan.FromHours(-6)) },
                new StatusUpdate { Description = "In transit to destination", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 6, 10, 6, 0, 0, TimeSpan.FromHours(-6)) },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 9, 12, 0, 0, TimeSpan.FromHours(-8)),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Seattle, WA", Timestamp = new DateTimeOffset(2026, 6, 6, 10, 0, 0, TimeSpan.FromHours(-8)) },
                new StatusUpdate { Description = "In transit", Location = "Portland, OR", Timestamp = new DateTimeOffset(2026, 6, 7, 8, 0, 0, TimeSpan.FromHours(-8)) },
                new StatusUpdate { Description = "Out for delivery", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 6, 9, 7, 30, 0, TimeSpan.FromHours(-8)) },
                new StatusUpdate { Description = "Delivered", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 6, 9, 11, 45, 0, TimeSpan.FromHours(-8)) },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Out for Delivery",
            Location = "Austin, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 10, 18, 0, 0, TimeSpan.FromHours(-6)),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Dallas, TX", Timestamp = new DateTimeOffset(2026, 6, 9, 8, 0, 0, TimeSpan.FromHours(-6)) },
                new StatusUpdate { Description = "Arrived at local facility", Location = "Austin, TX", Timestamp = new DateTimeOffset(2026, 6, 10, 4, 0, 0, TimeSpan.FromHours(-6)) },
                new StatusUpdate { Description = "Out for delivery", Location = "Austin, TX", Timestamp = new DateTimeOffset(2026, 6, 10, 8, 30, 0, TimeSpan.FromHours(-6)) },
            ]
        }
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

using System.Net.Http.Json;
using sv_1cfa675c18634d4d958ac8664a424033.Client.Models;

namespace sv_1cfa675c18634d4d958ac8664a424033.Client.Services;

public sealed class ShipmentServiceClient(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct)
            ?? throw new InvalidOperationException("Received empty response from server.");
    }
}

